ali = Insan()

class Insan:
  def __init__(self, isim):
    self.isim = isim

  def __str__(self):
    return f'İnsan nesnesi: {self.isim}'

p = Insan('Ayşe')
print(p) # __str__ olmasa anlamsız bir hafıza adresi yazardı
